#' CLI Interface
#' Command-line interface for managing the auto-improvement cycle.
#' @export
run_cli <- function(command = 'status', config_path = NULL, verbose = FALSE) { switch(command, status = { cycle <- ImprovementCycle(config_path = config_path); status <- cycle(); cat('Auto-Improvement System Status\n'); cat('==============================\n'); cat('Running:', status, '\n'); cat('Total Cycles:', status, '\n'); cat('Successful Cycles:', status, '\n'); cat('Agents Initialized:', status, '\n'); if (verbose) { cat('\nLLM Rate Limits:\n'); print(status) } }, 'run-cycle' = { cycle <- ImprovementCycle(config_path = config_path); cycle(); result <- cycle(); cat('Cycle Completed:', result, '\n'); cat('Phase:', result, '\n'); cat('Patterns Identified:', result, '\n'); cycle() }, continuous = { cycle <- ImprovementCycle(config_path = config_path); cycle(); cycle_count <- 0; while (TRUE) { cycle_count <- cycle_count + 1; cat('\nRunning cycle', cycle_count, '...\n'); tryCatch({ result <- cycle(); if (result == 'completed') cat('Cycle', cycle_count, 'completed successfully\n'); Sys.sleep(3600) }, interrupt = function(e) { cat('\nStopping continuous improvement...\n'); break }, error = function(e) { cat('Cycle', cycle_count, 'error:', e, '\n'); Sys.sleep(60) }) }; cycle() }, 'test-llm' = { llm <- GeminiService(); llm(); response <- llm('What are the key principles of quantum computing?'); cat('LLM Response:\n'); cat(response, '\n'); llm() }, 'generate-config' = { config <- list(project = 'q_mini_wasm_v2', version = '1.0.0', gemini = list(api_key_env = 'GEMINI_API_KEY', model = 'gemini-3-flash-preview', temperature = 0.7, max_tokens = 8192, rate_limits = list(rpm = 15, tpm = 1000000, rpd = 1500))); jsonlite::write_json(config, 'agents/config.json', pretty = TRUE, auto_unbox = TRUE); cat('Configuration generated: agents/config.json\n') }, { cat('Unknown command:', command, '\n'); cat('Available commands: status, run-cycle, continuous, test-llm, generate-config\n') }) }
